(5067516, 739540, 98141, '<td valign="top">Clever title/idea. I think I would like it more with a more inclusive dof.</td>', 'Clever title/idea. I think I would like it more with a more inclusive dof.', '2008-11-17 08:41:06.000000', NULL, 1),
(5067518, 739665, 95579, '<td valign="top">I think I would have chosen a different title for reasons I wont go into..<br/>Love the shot though - 7</td>', 'I think I would have chosen a different title for reasons I wont go into..Love the shot though - 7', '2008-11-17 08:41:42.000000', NULL, 1),
(5067520, 739676, 43774, '<td valign="top">Wow! This is gorgeous!</td>', 'Wow! This is gorgeous!', '2008-11-17 08:43:59.000000', NULL, 1),
(5067521, 739565, 43774, '<td valign="top">So cute</td>', 'So cute', '2008-11-17 08:44:05.000000', NULL, 1),
(5067522, 739613, 43774, '<td valign="top">I love this!</td>', 'I love this!', '2008-11-17 08:44:22.000000', NULL, 1),
(5067524, 739697, 43774, '<td valign="top">I really like this, great DOF as well.</td>', 'I really like this, great DOF as well.', '2008-11-17 08:44:30.000000', NULL, 1),
(5067526, 739530, 43774, '<td valign="top">Are you the coffee artist or did you buy this? I think it''s really neat, well photographed too.</td>', 'Are you the coffee artist or did you buy this? I think it''s really neat, well photographed too.', '2008-11-17 08:45:03.000000', NULL, 1),
(5067529, 739510, 43774, '<td valign="top">Nice!! I like the DOF and bokeh.</td>', 'Nice!! I like the DOF and bokeh.', '2008-11-17 08:45:20.000000', NULL, 1),
(5067530, 739627, 43774, '<td valign="top">Very cute.</td>', 'Very cute.', '2008-11-17 08:45:29.000000', NULL, 1),
(5067531, 739530, 98141, '<td valign="top">Looks absolutely delicious. Should be hanging up in a coffee shop in February.</td>', 'Looks absolutely delicious. Should be hanging up in a coffee shop in February.', '2008-11-17 08:45:43.000000', NULL, 1),
(5067533, 739583, 43774, '<td valign="top">A different twist on this photo, to make the reflection a different colour. Nice.</td>', 'A different twist on this photo, to make the reflection a different colour. Nice.', '2008-11-17 08:47:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5067534, 739543, 98141, '<td valign="top">Fun card shot, I love the feeling of motion here and the composition. Don''t care for the flash shadows on a few of the cards, but I see how that might not have been avoidable. Subject is ordinary.</td>', 'Fun card shot, I love the feeling of motion here and the composition. Don''t care for the flash shadows on a few of the cards, but I see how that might not have been avoidable. Subject is ordinary.', '2008-11-17 08:48:11.000000', NULL, 1),
(5067535, 739616, 98141, '<td valign="top">I like the colors. I don''t care for the white edge/frame at all. Can''t say the subject is particularly interesting. I think I''d like it better if the heart were smaller in the frame and more to the side.</td>', 'I like the colors. I don''t care for the white edge/frame at all. Can''t say the subject is particularly interesting. I think I''d like it better if the heart were smaller in the frame and more to the side.', '2008-11-17 08:50:35.000000', NULL, 1),
(5067536, 739386, 98141, '<td valign="top">Interesting interpretation, but I wouldn''t get it without the title. Doesn''t feel very sharp, almost like there were camera shake, did you use a tripod? I think you have good composition.</td>', 'Interesting interpretation, but I wouldn''t get it without the title. Doesn''t feel very sharp, almost like there were camera shake, did you use a tripod? I think you have good composition.', '2008-11-17 08:51:54.000000', NULL, 1),
(5067538, 739466, 98141, '<td valign="top">Interesting, for some reason I really like this, but I can''t really tell you why. Interesting dof. The red/pink in the upper left corner is a bit distracting.</td>', 'Interesting, for some reason I really like this, but I can''t really tell you why. Interesting dof. The red/pink in the upper left corner is a bit distracting.', '2008-11-17 08:54:51.000000', NULL, 1),
(5067539, 739692, 88718, '<td valign="top">Exceptionallz nice composition and colour combination</td>', 'Exceptionallz nice composition and colour combination', '2008-11-17 08:55:46.000000', NULL, 1),
(5067540, 739616, 88718, '<td valign="top">The blue and silver are very attractive on this background</td>', 'The blue and silver are very attractive on this background', '2008-11-17 08:56:26.000000', NULL, 1),
(5067541, 739421, 98141, '<td valign="top">Where is the focus? I think that the whole lady and arm should be in focus and the background should be softer. Right now the plants are distracting in the back. I think that by leaving out the woman''s face/reaction, a lot of the emotion/story is lost.</td>', 'Where is the focus? I think that the whole lady and arm should be in focus and the background should be softer. Right now the plants are distracting in the back. I think that by leaving out the woman''s face/reaction, a lot of the emotion/story is lost.', '2008-11-17 08:58:12.000000', NULL, 1),
(5067542, 739609, 98141, '<td valign="top">Ew, cool. Great colors, great effects.</td>', 'Ew, cool. Great colors, great effects.', '2008-11-17 08:58:52.000000', NULL, 1),
(5067544, 739424, 98141, '<td valign="top">Interesting angle, I think this would look nice with a little more saturation.</td>', 'Interesting angle, I think this would look nice with a little more saturation.', '2008-11-17 09:00:21.000000', NULL, 1),
(5067546, 739676, 98141, '<td valign="top">The lines in the sand look like fire, or a tree, and the rock is really cool. You definitely captured the all-natural feel.</td>', 'The lines in the sand look like fire, or a tree, and the rock is really cool. You definitely captured the all-natural feel.', '2008-11-17 09:01:14.000000', NULL, 1),
(5067547, 739566, 98141, '<td valign="top">Feels a little too overexposed, wish the notes were darker. Clever idea.</td>', 'Feels a little too overexposed, wish the notes were darker. Clever idea.', '2008-11-17 09:02:05.000000', NULL, 1),
(5067550, 739669, 98141, '<td valign="top">Sorry, I don''t get this. Flower vortex does not equal heart in my mind. Great colors though.</td>', 'Sorry, I don''t get this. Flower vortex does not equal heart in my mind. Great colors though.', '2008-11-17 09:17:22.000000', NULL, 1),
(5067551, 739720, 98141, '<td valign="top">Love this, the textture and lighting are fabulous.</td>', 'Love this, the textture and lighting are fabulous.', '2008-11-17 09:17:34.000000', NULL, 1),
(5067552, 739668, 98141, '<td valign="top">I think if her hair were lighter so the only thing that really jumped out was the heart, I would like it better. Right now the hair steals the show in my opinion.</td>', 'I think if her hair were lighter so the only thing that really jumped out was the heart, I would like it better. Right now the hair steals the show in my opinion.', '2008-11-17 09:18:24.000000', NULL, 1),
(5067553, 739625, 98141, '<td valign="top">The focus on the pendent doesn''t feel sharp to me. I like using the mirror to frame it. Feels basic, nothing pops.</td>', 'The focus on the pendent doesn''t feel sharp to me. I like using the mirror to frame it. Feels basic, nothing pops.', '2008-11-17 09:19:49.000000', NULL, 1),
(5067554, 739247, 98141, '<td valign="top">Cool leaf, perfect color and everything. Wish the focus were a little sharper on the eyes, and maybe that they were alittle brighter (not in shadow).</td>', 'Cool leaf, perfect color and everything. Wish the focus were a little sharper on the eyes, and maybe that they were alittle brighter (not in shadow).', '2008-11-17 09:20:49.000000', NULL, 1),
(5067555, 739527, 3102, '<td valign="top">I would assume this is Bear''s entry... not only because of the style and subject, but because he''s probably the only member of the site who would use the word "Detritus" in a title :)  Best wishes for a speedy recovery!</td>', 'I would assume this is Bear''s entry... not only because of the style and subject, but because he''s probably the only member of the site who would use the word "Detritus" in a title :)  Best wishes for a speedy recovery!', '2008-11-17 09:21:01.000000', NULL, 1),
(5067556, 739719, 98141, '<td valign="top">Clever title, cool shot. I like the lighting on the shot glass.</td>', 'Clever title, cool shot. I like the lighting on the shot glass.', '2008-11-17 09:21:23.000000', NULL, 1),
(5067557, 739488, 98141, '<td valign="top">I like this, but I can''t really put my finger on why. Feels a little overcropped, though. Nice colors.</td>', 'I like this, but I can''t really put my finger on why. Feels a little overcropped, though. Nice colors.', '2008-11-17 09:22:32.000000', NULL, 1),
(5067558, 739531, 98141, '<td valign="top">I''d like this better without the second heart.</td>', 'I''d like this better without the second heart.', '2008-11-17 09:23:13.000000', NULL, 1),
(5067561, 739629, 98141, '<td valign="top">Very clever, I like the shadow being red but the ring being clear, looks cool. Nice colors, nice contrast.</td>', 'Very clever, I like the shadow being red but the ring being clear, looks cool. Nice colors, nice contrast.', '2008-11-17 09:23:54.000000', NULL, 1),
(5067564, 739662, 98141, '<td valign="top">I don''t care for the processing/how soft the b&amp;w leaves are. Clever shot.</td>', 'I don''t care for the processing/how soft the b&w leaves are. Clever shot.', '2008-11-17 09:24:40.000000', NULL, 1),
(5067567, 739677, 98141, '<td valign="top">This is making me so hungry. I like that this is a different take on the theme, but that without the title we could still get it. Should be in a menu somewhere. Should be in my tummy!!</td>', 'This is making me so hungry. I like that this is a different take on the theme, but that without the title we could still get it. Should be in a menu somewhere. Should be in my tummy!!', '2008-11-17 09:25:43.000000', NULL, 1),
(5067568, 739670, 98141, '<td valign="top">Blackness in upper left corner is distracting. Wish the white were a little crisper.</td>', 'Blackness in upper left corner is distracting. Wish the white were a little crisper.', '2008-11-17 09:26:41.000000', NULL, 1),
(5067569, 739667, 98141, '<td valign="top">Cute, I never saw the bride and groom ones before. Nice lighting. Very straightforward.</td>', 'Cute, I never saw the bride and groom ones before. Nice lighting. Very straightforward.', '2008-11-17 09:28:27.000000', NULL, 1),
(5067571, 739545, 98141, '<td valign="top">Interesting, feels like grafitti. Would like to see the heart a little more off-center for more eye-grabbing composition.</td>', 'Interesting, feels like grafitti. Would like to see the heart a little more off-center for more eye-grabbing composition.', '2008-11-17 09:30:01.000000', NULL, 1),
(5067573, 739718, 98141, '<td valign="top">Funky! I like it.</td>', 'Funky! I like it.', '2008-11-17 09:30:21.000000', NULL, 1),
(5067574, 739613, 98141, '<td valign="top">Beautiful composition, beautiful colors, great idea.</td>', 'Beautiful composition, beautiful colors, great idea.', '2008-11-17 09:30:44.000000', NULL, 1),
(5067575, 739721, 98141, '<td valign="top">I think this is a much more interesting way of photographing jewelry, well done.</td>', 'I think this is a much more interesting way of photographing jewelry, well done.', '2008-11-17 09:31:17.000000', NULL, 1),
(5067579, 739461, 98141, '<td valign="top">The heart that is half-hidden by her head bugs me a little. I''d like her expression to be more lovey-dovey, she''s got the Mona Lisa smile going on right now.</td>', 'The heart that is half-hidden by her head bugs me a little. I''d like her expression to be more lovey-dovey, she''s got the Mona Lisa smile going on right now.', '2008-11-17 09:34:36.000000', NULL, 1),
(5067581, 739713, 98141, '<td valign="top">I thought of something like this, you executed it well. Nice title too. Great lighting.</td>', 'I thought of something like this, you executed it well. Nice title too. Great lighting.', '2008-11-17 09:34:59.000000', NULL, 1),
(5067582, 739711, 98141, '<td valign="top">Nice composition, I think the red in the bottom right is distracting though.</td>', 'Nice composition, I think the red in the bottom right is distracting though.', '2008-11-17 09:35:44.000000', NULL, 1),
(5067585, 739484, 98141, '<td valign="top">THis is cool, but feels much like a cg graphic rather than a photo. Would like the composition better if the "main" heart were not in the center.</td>', 'THis is cool, but feels much like a cg graphic rather than a photo. Would like the composition better if the "main" heart were not in the center.', '2008-11-17 09:36:43.000000', NULL, 1),
(5067586, 739516, 76598, '<td valign="top">I really like the feel of the image, the colors are very good and the selective lighting is excellent.....HOWEVER, the depth of field is far too shallow and the image really loses it because of that.</td>', 'I really like the feel of the image, the colors are very good and the selective lighting is excellent.....HOWEVER, the depth of field is far too shallow and the image really loses it because of that.', '2008-11-17 09:37:15.000000', NULL, 1),
(5067587, 739672, 98141, '<td valign="top">I love the light framing on the heart. The light horizon in the back provides a feeling of depth. Nice.</td>', 'I love the light framing on the heart. The light horizon in the back provides a feeling of depth. Nice.', '2008-11-17 09:37:17.000000', NULL, 1),
(5067588, 739479, 98141, '<td valign="top">Great title, great lighting.</td>', 'Great title, great lighting.', '2008-11-17 09:37:57.000000', NULL, 1),
(5067589, 739683, 98141, '<td valign="top">Cool lighting, mysterious.</td>', 'Cool lighting, mysterious.', '2008-11-17 09:38:25.000000', NULL, 1),
(5067590, 739587, 98141, '<td valign="top">Don''t care much for the frame.</td>', 'Don''t care much for the frame.', '2008-11-17 09:38:46.000000', NULL, 1),
(5067592, 739721, 76598, '<td valign="top">Cute idea, the selective desaturation works for the image, somehow the image is not dynamic....the picture or whatever it is on the wall is very dark in an otherwise light image, my preference would have been for the locket to be further into the image and perhaps a little bit more depth of field to see more of the parents.</td>', 'Cute idea, the selective desaturation works for the image, somehow the image is not dynamic....the picture or whatever it is on the wall is very dark in an otherwise light image, my preference would have been for the locket to be further into the image and perhaps a little bit more depth of field to see more of the parents.', '2008-11-17 09:39:16.000000', NULL, 1),
(5067594, 739666, 98141, '<td valign="top">Interesting, would love to read how you made this. So many lines going on, lots of interest.</td>', 'Interesting, would love to read how you made this. So many lines going on, lots of interest.', '2008-11-17 09:39:39.000000', NULL, 1),
(5067596, 739370, 76598, '<td valign="top">I fear a lot of people will miss the hearts in the water drops, a very novel idea!!  I might have chosen to expose a little less stem...but a great image.</td>', 'I fear a lot of people will miss the hearts in the water drops, a very novel idea!!  I might have chosen to expose a little less stem...but a great image.', '2008-11-17 09:40:16.000000', NULL, 1),
(5067597, 739372, 98141, '<td valign="top">Nice dof, and I''m jealous of wherever you are that the leaves are still green, but the stem in front and the shadow on the leaf are distracting.</td>', 'Nice dof, and I''m jealous of wherever you are that the leaves are still green, but the stem in front and the shadow on the leaf are distracting.', '2008-11-17 09:40:26.000000', NULL, 1),
(5067598, 739686, 98141, '<td valign="top">Cool shot, wish the focus on the figurine were a little sharper.</td>', 'Cool shot, wish the focus on the figurine were a little sharper.', '2008-11-17 09:41:10.000000', NULL, 1),
(5067599, 739594, 98141, '<td valign="top">Beautiful, soft, romantic.</td>', 'Beautiful, soft, romantic.', '2008-11-17 09:41:21.000000', NULL, 1),
(5067601, 738961, 98141, '<td valign="top">Snapshot. Lighting from the flash is too harsh. Would like a broader dof better. Top right and bottom left corners are distracting.</td>', 'Snapshot. Lighting from the flash is too harsh. Would like a broader dof better. Top right and bottom left corners are distracting.', '2008-11-17 09:42:42.000000', NULL, 1),
(5067603, 739628, 98141, '<td valign="top">Would love to see the original after the challenge :) It''s a cool pic, but feels more like a graphic than a photo.</td>', 'Would love to see the original after the challenge :) It''s a cool pic, but feels more like a graphic than a photo.', '2008-11-17 09:43:33.000000', NULL, 1),
(5067604, 738054, 98141, '<td valign="top">I''ve seen a couple of shots using leaves as hearts, and this is my favorite so far. Great color choice. Nice composition and dof.</td>', 'I''ve seen a couple of shots using leaves as hearts, and this is my favorite so far. Great color choice. Nice composition and dof.', '2008-11-17 09:44:04.000000', NULL, 1),
(5067606, 739702, 98141, '<td valign="top">I wish their legs were touching. Something about this feels like dolls to me.</td>', 'I wish their legs were touching. Something about this feels like dolls to me.', '2008-11-17 09:45:08.000000', NULL, 1),
(5067608, 739475, 98141, '<td valign="top">Background is distracting, wish it were less busy.</td>', 'Background is distracting, wish it were less busy.', '2008-11-17 09:46:03.000000', NULL, 1),
(5067609, 739626, 98141, '<td valign="top">Nice composition. I like the antique feel with the colors.</td>', 'Nice composition. I like the antique feel with the colors.', '2008-11-17 09:46:29.000000', NULL, 1),
(5067610, 739516, 98141, '<td valign="top">I wish the whole heart were in focus. Lovely colors.</td>', 'I wish the whole heart were in focus. Lovely colors.', '2008-11-17 09:46:57.000000', NULL, 1),
(5067611, 739681, 98141, '<td valign="top">Composition is dull. Bottom right is distracting.</td>', 'Composition is dull. Bottom right is distracting.', '2008-11-17 09:47:30.000000', NULL, 1),
(5067612, 739229, 98141, '<td valign="top">To me, the lighting is too bright for this topic and I don''t see the connection between the purse and the action.</td>', 'To me, the lighting is too bright for this topic and I don''t see the connection between the purse and the action.', '2008-11-17 09:48:56.000000', NULL, 1),
(5067614, 739307, 98141, '<td valign="top">I like that you found a heart rather than making one, but I wish the details on the bug were sharper.</td>', 'I like that you found a heart rather than making one, but I wish the details on the bug were sharper.', '2008-11-17 09:49:39.000000', NULL, 1),
(5067615, 739600, 98141, '<td valign="top">Nice dof, might like it better without the dude.</td>', 'Nice dof, might like it better without the dude.', '2008-11-17 09:50:39.000000', NULL, 1),
(5067617, 739665, 98141, '<td valign="top">This is cool, but I''m not sure what I''m looking at here? Don''t care for the frame.</td>', 'This is cool, but I''m not sure what I''m looking at here? Don''t care for the frame.', '2008-11-17 09:52:17.000000', NULL, 1),
(5067618, 739689, 98141, '<td valign="top">I''m a sucker for these kinds of shots. Nice lighting.</td>', 'I''m a sucker for these kinds of shots. Nice lighting.', '2008-11-17 09:53:06.000000', NULL, 1),
(5067620, 739413, 98141, '<td valign="top">I wish the thumbs were tilted in a little more so the hands made a heart shape too.</td>', 'I wish the thumbs were tilted in a little more so the hands made a heart shape too.', '2008-11-17 09:54:07.000000', NULL, 1),
(5067622, 739619, 98141, '<td valign="top">Feels rough, natural.</td>', 'Feels rough, natural.', '2008-11-17 09:54:38.000000', NULL, 1),
(5067624, 739216, 98141, '<td valign="top">That makes two shots so far of heart+prison themes. Not sure I get that, but this shot is awesome. Great colors, great lines, great focus.</td>', 'That makes two shots so far of heart+prison themes. Not sure I get that, but this shot is awesome. Great colors, great lines, great focus.', '2008-11-17 09:55:31.000000', NULL, 1),
(5067625, 739627, 98141, '<td valign="top">Love the pupils, this is cool, nice composition.</td>', 'Love the pupils, this is cool, nice composition.', '2008-11-17 09:56:01.000000', NULL, 1),
(5067626, 739688, 98141, '<td valign="top">Lovely colors, bottom left is distracting.</td>', 'Lovely colors, bottom left is distracting.', '2008-11-17 09:56:27.000000', NULL, 1),
(5067628, 739468, 98141, '<td valign="top">Simple. Wish the focus were sharper. Would like the subject to be off-center.</td>', 'Simple. Wish the focus were sharper. Would like the subject to be off-center.', '2008-11-17 09:57:31.000000', NULL, 1),
(5067629, 739583, 98141, '<td valign="top">Cool colors, nice focus, nice composition.</td>', 'Cool colors, nice focus, nice composition.', '2008-11-17 09:59:20.000000', NULL, 1),
(5067632, 739714, 98141, '<td valign="top">Not really sure what I''m looking at, but for some reason I find this very intriguing. Composition is a little dull with the subject right in the center.</td>', 'Not really sure what I''m looking at, but for some reason I find this very intriguing. Composition is a little dull with the subject right in the center.', '2008-11-17 10:00:12.000000', NULL, 1),
(5067656, 739627, 36382, '<td valign="top">He nailed the expression.  Love this one.  My fave by far.</td>', 'He nailed the expression.  Love this one.  My fave by far.', '2008-11-17 10:17:38.000000', NULL, 1),
(5067754, 739300, 67152, '<td valign="top">i really love the connection of the title to the feeling of the image</td>', 'i really love the connection of the title to the feeling of the image', '2008-11-17 11:33:38.000000', NULL, 1),
(5067757, 739626, 67152, '<td valign="top">wonderfully composed image - the feeling expressed by the father and child and the repeated theme of the two hearts makes the shot</td>', 'wonderfully composed image - the feeling expressed by the father and child and the repeated theme of the two hearts makes the shot', '2008-11-17 11:34:39.000000', NULL, 1),
(5067758, 739718, 67152, '<td valign="top">really nice use of a DPC friendly technique - a bit busy on the hearts IMO</td>', 'really nice use of a DPC friendly technique - a bit busy on the hearts IMO', '2008-11-17 11:35:05.000000', NULL, 1),
(5067759, 739370, 67152, '<td valign="top">nice use of a DPC friendly technique - it is executed very well here</td>', 'nice use of a DPC friendly technique - it is executed very well here', '2008-11-17 11:35:32.000000', NULL, 1),
(5067762, 739565, 67152, '<td valign="top">a great deal of fun to view - that is one heck of a portait - good thing they had pretty attractive feet!</td>', 'a great deal of fun to view - that is one heck of a portait - good thing they had pretty attractive feet!', '2008-11-17 11:36:04.000000', NULL, 1),
(5067763, 739676, 67152, '<td valign="top">fantastic vision to see the possibilities here - one of my favs for the challenge</td>', 'fantastic vision to see the possibilities here - one of my favs for the challenge', '2008-11-17 11:36:31.000000', NULL, 1),
(5067764, 739510, 67152, '<td valign="top">excellent execution of this shot - it has a feeling of an image by ''you know who"</td>', 'excellent execution of this shot - it has a feeling of an image by ''you know who"', '2008-11-17 11:37:37.000000', NULL, 1),
(5067765, 739530, 67152, '<td valign="top">magazine worthy - excellent shot -  the tilt of the cup, the warmth of the browns, the details in the heart</td>', 'magazine worthy - excellent shot -  the tilt of the cup, the warmth of the browns, the details in the heart', '2008-11-17 11:38:44.000000', NULL, 1),
(5067766, 738727, 67152, '<td valign="top">i love this image - the title and the minimalistic approach to the shot are a perfect match</td>', 'i love this image - the title and the minimalistic approach to the shot are a perfect match', '2008-11-17 11:39:09.000000', NULL, 1),
(5067768, 739372, 67152, '<td valign="top">really nice details - i just wish the branch that is throwing a shadow on the leaf were pruned away for this one</td>', 'really nice details - i just wish the branch that is throwing a shadow on the leaf were pruned away for this one', '2008-11-17 11:39:42.000000', NULL, 1),
(5067770, 739629, 67152, '<td valign="top">very good use of a familiar DPC technique</td>', 'very good use of a familiar DPC technique', '2008-11-17 11:40:05.000000', NULL, 1),
(5067771, 738997, 67152, '<td valign="top">lovely portrait - the cross processed feel of this image really gives this a bit extra to hold my attention</td>', 'lovely portrait - the cross processed feel of this image really gives this a bit extra to hold my attention', '2008-11-17 11:40:46.000000', NULL, 1),
(5067776, 739372, 73235, '<td valign="top">I like the contrast you brought out, the details and the muted background. I guess there was no way to avoid the shadow and the wine going through the leave?</td>', 'I like the contrast you brought out, the details and the muted background. I guess there was no way to avoid the shadow and the wine going through the leave?', '2008-11-17 11:44:37.000000', NULL, 1),
