INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5069407, 739683, 73235, '<td valign="top">While not a literal interpretation of heart, your picture shows strongly the emotion the heart stands for. 10</td>', 'While not a literal interpretation of heart, your picture shows strongly the emotion the heart stands for. 10', '2008-11-18 11:54:05.000000', NULL, 1),
(5069413, 739673, 73235, '<td valign="top">Filling the frame with hearts, very nice</td>', 'Filling the frame with hearts, very nice', '2008-11-18 11:54:56.000000', NULL, 1),
(5069419, 739678, 73235, '<td valign="top">very emotional and strong, may be you could try an other background color? An other color could bring out the heart a little more?</td>', 'very emotional and strong, may be you could try an other background color? An other color could bring out the heart a little more?', '2008-11-18 11:57:11.000000', NULL, 1),
(5069420, 739721, 73235, '<td valign="top">very loveable interpretation</td>', 'very loveable interpretation', '2008-11-18 11:58:11.000000', NULL, 1),
(5069424, 739634, 73235, '<td valign="top">very funny title and so right on. looks like you had some fun, putting this together</td>', 'very funny title and so right on. looks like you had some fun, putting this together', '2008-11-18 11:59:44.000000', NULL, 1),
(5069431, 739625, 73235, '<td valign="top">great focus, I mean the focus and the focus on a subject (LOL). good way to capture the heart and the viewer with the curved line, while the viewer is introduced by the leading handle. Well composed.</td>', 'great focus, I mean the focus and the focus on a subject (LOL). good way to capture the heart and the viewer with the curved line, while the viewer is introduced by the leading handle. Well composed.', '2008-11-18 12:01:58.000000', NULL, 1),
(5069448, 739562, 73235, '<td valign="top">by now you probably heard enough about he blown out parts of the heart, but I don''t mind them at all. They create a strong contrast to the dark tree trunk. An what''s what you picture lives off, the contrast.</td>', 'by now you probably heard enough about he blown out parts of the heart, but I don''t mind them at all. They create a strong contrast to the dark tree trunk. An what''s what you picture lives off, the contrast.', '2008-11-18 12:11:10.000000', NULL, 1),
(5069450, 738844, 73235, '<td valign="top">great composition nad placement of all elements here.</td>', 'great composition nad placement of all elements here.', '2008-11-18 12:12:02.000000', NULL, 1),
(5069456, 739713, 73235, '<td valign="top">looking at you pictre, I get some mixed feelings. your title and the heart convey a warm loving emotion while your model''s expression seems to be rather cool. There is abolsutely nothing wrong with the technical aspects of your shot.</td>', 'looking at you pictre, I get some mixed feelings. your title and the heart convey a warm loving emotion while your model''s expression seems to be rather cool. There is abolsutely nothing wrong with the technical aspects of your shot.', '2008-11-18 12:19:52.000000', NULL, 1),
(5069461, 739598, 73235, '<td valign="top">you wanted to prvoke reactions, didn''t you? THe face is nicely in focus, the heart seems to be more on the soft side. But then again it''s not propared and really is soft tissue.</td>', 'you wanted to prvoke reactions, didn''t you? THe face is nicely in focus, the heart seems to be more on the soft side. But then again it''s not propared and really is soft tissue.', '2008-11-18 12:23:45.000000', NULL, 1),
(5069462, 739671, 3087, '<td valign="top">Nice idea. I''d say that the grapes could have done with a wash/ polishing wipe beforehand as the white bloom on htem detracts a little, for me.</td>', 'Nice idea. I''d say that the grapes could have done with a wash/ polishing wipe beforehand as the white bloom on htem detracts a little, for me.', '2008-11-18 12:25:10.000000', NULL, 1),
(5069464, 739676, 3087, '<td valign="top">Beautiful, so artistic. I''m not sure this represents "heart" to me, the shape could just about be said to be a little heart-like... but I love the image.</td>', 'Beautiful, so artistic. I''m not sure this represents "heart" to me, the shape could just about be said to be a little heart-like... but I love the image.', '2008-11-18 12:25:58.000000', NULL, 1),
(5069465, 739531, 3087, '<td valign="top">Less is more. The foreground heart detracts hugely for me, especially with the lack of focus (and I''m often a fan of shallow DOF).</td>', 'Less is more. The foreground heart detracts hugely for me, especially with the lack of focus (and I''m often a fan of shallow DOF).', '2008-11-18 12:26:44.000000', NULL, 1),
(5069467, 739664, 3087, '<td valign="top">Like the toning of the black and white and the heavy grain. I like the hair at the nape of the neck and the tatoo itself. The ears seem too dominant for me, perhaps because of the light reflected on them and the symmetry. Overall, seems lacking in sharpness.</td>', 'Like the toning of the black and white and the heavy grain. I like the hair at the nape of the neck and the tatoo itself. The ears seem too dominant for me, perhaps because of the light reflected on them and the symmetry. Overall, seems lacking in sharpness.', '2008-11-18 12:27:41.000000', NULL, 1),
(5069469, 739713, 3087, '<td valign="top">Cute!</td>', 'Cute!', '2008-11-18 12:27:54.000000', NULL, 1),
(5069472, 739626, 3087, '<td valign="top">A cliche and for good reason! I like the composition, I love the backlit adult and child, I think the colours reflected on the wet sand are lovely, and of course, the scraped heart works very well.</td>', 'A cliche and for good reason! I like the composition, I love the backlit adult and child, I think the colours reflected on the wet sand are lovely, and of course, the scraped heart works very well.', '2008-11-18 12:28:43.000000', NULL, 1),
(5069475, 739300, 3087, '<td valign="top">Interesting and great textures too.</td>', 'Interesting and great textures too.', '2008-11-18 12:29:38.000000', NULL, 1),
(5069477, 739372, 3087, '<td valign="top">Works well apart from the shadow across top left of leaf.</td>', 'Works well apart from the shadow across top left of leaf.', '2008-11-18 12:29:57.000000', NULL, 1),
(5069479, 739565, 3087, '<td valign="top">Ha! Feet love! I hate feet (it''s an odd phobia, I know and luckily, fairly mild) BUT I kind of like this!</td>', 'Ha! Feet love! I hate feet (it''s an odd phobia, I know and luckily, fairly mild) BUT I kind of like this!', '2008-11-18 12:30:38.000000', NULL, 1),
(5069481, 739689, 3087, '<td valign="top">Nice variation on an oft-used idea, good composition too.</td>', 'Nice variation on an oft-used idea, good composition too.', '2008-11-18 12:31:14.000000', NULL, 1),
(5069482, 739677, 3087, '<td valign="top">Dare to be different! Cute idea!</td>', 'Dare to be different! Cute idea!', '2008-11-18 12:31:27.000000', NULL, 1),
(5069484, 739510, 3087, '<td valign="top">Lovely sharp details, lovely texture within the ice and nice reflections from the ice and the melt-water. Great bokeh in that background too. All good.</td>', 'Lovely sharp details, lovely texture within the ice and nice reflections from the ice and the melt-water. Great bokeh in that background too. All good.', '2008-11-18 12:32:29.000000', NULL, 1),
(5069486, 739697, 3087, '<td valign="top">Like the colours, textures and shallow DOF. Interesting cut-out idea. Am not sure whether I''d prefer the more natural version without the window to the green leaf beneath...</td>', 'Like the colours, textures and shallow DOF. Interesting cut-out idea. Am not sure whether I''d prefer the more natural version without the window to the green leaf beneath...', '2008-11-18 12:33:25.000000', NULL, 1),
(5069487, 739698, 3087, '<td valign="top">I do like quirky long-exposures! Interesting!</td>', 'I do like quirky long-exposures! Interesting!', '2008-11-18 12:33:43.000000', NULL, 1),
(5069488, 739479, 3087, '<td valign="top">Fabulous composition, like that very much. Also like the shallow DOF blurring out the text a few lines in. Seems oversharpened but otherwise great.</td>', 'Fabulous composition, like that very much. Also like the shallow DOF blurring out the text a few lines in. Seems oversharpened but otherwise great.', '2008-11-18 12:34:45.000000', NULL, 1),
(5069491, 739715, 3087, '<td valign="top">Lovely capture of the city at night. Like the idea of the couple in the foreground. However, for me, in this image, their central position doesn''t work. Off to one side would work better, I think.</td>', 'Lovely capture of the city at night. Like the idea of the couple in the foreground. However, for me, in this image, their central position doesn''t work. Off to one side would work better, I think.', '2008-11-18 12:35:43.000000', NULL, 1),
(5069492, 739673, 3087, '<td valign="top">Ooooh heart bokeh! Cute!</td>', 'Ooooh heart bokeh! Cute!', '2008-11-18 12:35:53.000000', NULL, 1),
(5069500, 739628, 73235, '<td valign="top">wow, this is a real wide/wild interpretations. extra points for reativity.</td>', 'wow, this is a real wide/wild interpretations. extra points for reativity.', '2008-11-18 12:39:28.000000', NULL, 1),
(5069502, 739616, 73235, '<td valign="top">wow, well taken. I can see and feel it pop right out of my monitor. Almost tempted to reach out for it.</td>', 'wow, well taken. I can see and feel it pop right out of my monitor. Almost tempted to reach out for it.', '2008-11-18 12:40:38.000000', NULL, 1),
