(5069760, 739673, 30861, '<td valign="top">I really, really like this image. I can''t wait to see how it was made. I expect it will not score especially well, but I gave it a nine. I particulalry enjoy that you resisted color-shifting to the warmer end of the spectrum. Good luck</td>', 'I really, really like this image. I can''t wait to see how it was made. I expect it will not score especially well, but I gave it a nine. I particulalry enjoy that you resisted color-shifting to the warmer end of the spectrum. Good luck', '2008-11-18 15:41:13.000000', NULL, 1),
(5069768, 739300, 30861, '<td valign="top">This one touches me, the sense of hope that I may yet take flight :-) It''s my sort of image... You were brave to center gthe heart, but it is saved from tghe hum-drum by the asymmetrical location of the heart within the centered opening. 9 from me.</td>', 'This one touches me, the sense of hope that I may yet take flight :-) It''s my sort of image... You were brave to center gthe heart, but it is saved from tghe hum-drum by the asymmetrical location of the heart within the centered opening. 9 from me.', '2008-11-18 15:46:02.000000', NULL, 1),
(5069773, 739714, 30861, '<td valign="top">This is beautiful. The upper portion of the shadow on the right is a bit strange, but the subject hearts themselves are fantastic. While the image may be lacking in emotion or soul, it is nevertheless compelling. 8 from me.</td>', 'This is beautiful. The upper portion of the shadow on the right is a bit strange, but the subject hearts themselves are fantastic. While the image may be lacking in emotion or soul, it is nevertheless compelling. 8 from me.', '2008-11-18 15:48:09.000000', NULL, 1),
(5069774, 739609, 30861, '<td valign="top">This is bordering on the grotesque, yet it is oddly compelling. I keep coming back to it, and back, and back, so it is doing its job. A nine from me.</td>', 'This is bordering on the grotesque, yet it is oddly compelling. I keep coming back to it, and back, and back, so it is doing its job. A nine from me.', '2008-11-18 15:48:24.000000', NULL, 1),
