(5077215, 739662, 24486, '<td valign="top">I always did appreciate a good desat. Nice colours &amp; detail</td>', 'I always did appreciate a good desat. Nice colours & detail', '2008-11-21 04:01:47.000000', NULL, 1),
(5077217, 739539, 24486, '<td valign="top">Your piston is looking a bit worse for wear. Very clever concept</td>', 'Your piston is looking a bit worse for wear. Very clever concept', '2008-11-21 04:03:33.000000', NULL, 1),
(5077220, 739583, 24486, '<td valign="top">Great, I''ll be humming this for the rest of the night. A clever twist on a clichéd effect. I like it.</td>', 'Great, I''ll be humming this for the rest of the night. A clever twist on a clichéd effect. I like it.', '2008-11-21 04:10:36.000000', NULL, 1),
(5077223, 739594, 24486, '<td valign="top">This has a nice flow to it</td>', 'This has a nice flow to it', '2008-11-21 04:36:00.000000', NULL, 1),
(5077225, 739698, 24486, '<td valign="top">This must have been fun to photograph with all the jaffas wondering why someone is standing in the middle of an intersction holding up a big heart.</td>', 'This must have been fun to photograph with all the jaffas wondering why someone is standing in the middle of an intersction holding up a big heart.', '2008-11-21 04:42:16.000000', NULL, 1),
(5077456, 739543, 76430, '<td valign="top">Lots of hearts!  Were these thrown and quickly shot or somehow placed in those positions?  Either way looks sort of difficult.  The lighting is a bit harsh and there are 14 cards.</td>', 'Lots of hearts!  Were these thrown and quickly shot or somehow placed in those positions?  Either way looks sort of difficult.  The lighting is a bit harsh and there are 14 cards.', '2008-11-21 10:19:51.000000', NULL, 1),
(5077965, 739229, 3032, '<td valign="top">Looks like a Schiffmacher</td>', 'Looks like a Schiffmacher', '2008-11-21 16:37:18.000000', NULL, 1),
(5077966, 739664, 3032, '<td valign="top">Very nice photo, very nice tattoo. I like the assymetrical design of it, very cool.</td>', 'Very nice photo, very nice tattoo. I like the assymetrical design of it, very cool.', '2008-11-21 16:38:30.000000', NULL, 1),
(5077967, 739717, 3032, '<td valign="top">Much cooler sport than it looks.</td>', 'Much cooler sport than it looks.', '2008-11-21 16:42:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5078187, 739413, 62187, '<td valign="top">Beats the ''Heart Rock'' entry all to heck!</td>', 'Beats the ''Heart Rock'' entry all to heck!', '2008-11-21 20:35:14.000000', NULL, 1),
